/**
 * 02-hierarchy.js
 *
 * Hierarchy and step-ordering utilities for Logic Builder steps. This file owns parent/child relationships, grouped ordering, step numbering, and child-step creation.
 * Auto-generated documentation comments explain function purpose, expected inputs, and module sections without changing runtime behavior.
 */

// -----------------------------------------------------------------------------
// Hierarchy normalization and grouped ordering
// -----------------------------------------------------------------------------
/**
 * Ensures every step has parent, branch, and sort metadata before hierarchy rendering.
 */
function normalizeHierarchyFields(steps = state.audit.steps || []) {
  steps.forEach((step, index) => {
    if (!Object.prototype.hasOwnProperty.call(step, "parentId"))
      step.parentId = null;
    if (!step.branchType) step.branchType = step.parentId ? "then" : "root";
    if (!Number.isFinite(Number(step.sortOrder))) step.sortOrder = index;
  });
  atlasNormalizeStepOrderGroups?.({ preserveExistingOrder: true });
}
/**
 * Returns the required business-order group for a step.
 * @param {any} step - Logic step object being read or modified.
 */
function atlasStepOrderGroup(step) {
  if (!step) return 40;
  if (step.autoGeneratedReference || step.step_type === "reference_source")
    return 10;
  if (step.step_type === "join") return 20;
  if (step.step_type === "create_column") return 30;
  return 40;
}
// -----------------------------------------------------------------------------
// Cached hierarchy index
// -----------------------------------------------------------------------------
// Steps are mutated in place across the app, so a cached index is reused only
// while every step still has the same identity, position, and ordering fields.
// That check is one linear pass; without the cache every sibling lookup filtered
// and sorted the whole step list, which made large audits quadratic.
const ATLAS_STEP_SNAPSHOT_WIDTH = 8;
const atlasStepHierarchyCache = new WeakMap();
const atlasStepIdPositions = new WeakMap();

/**
 * Returns true when a cached snapshot still describes the step list.
 * @param {Array} snapshot - Flat snapshot recorded by atlasStepHierarchyIndex.
 * @param {Array} steps - Current step list.
 */
function atlasStepSnapshotMatches(snapshot, steps) {
  if (snapshot.length !== steps.length * ATLAS_STEP_SNAPSHOT_WIDTH)
    return false;
  for (let i = 0, o = 0; i < steps.length; i += 1) {
    const step = steps[i];
    if (
      snapshot[o++] !== step ||
      snapshot[o++] !== step.id ||
      !Object.is(snapshot[o++], step.parentId) ||
      !Object.is(snapshot[o++], step.sortOrder) ||
      snapshot[o++] !== step.step_type ||
      snapshot[o++] !== step.autoGeneratedReference ||
      snapshot[o++] !== step.enabled ||
      snapshot[o++] !== step.branchType
    )
      return false;
  }
  return true;
}

/**
 * Returns ordered children by parent for a step list, plus a per-index cache of
 * flattened hierarchy entries. Rebuilt whenever the step list changes shape.
 * @param {Array} steps - Step list to index.
 */
function atlasStepHierarchyIndex(steps) {
  const cached = atlasStepHierarchyCache.get(steps);
  if (cached && atlasStepSnapshotMatches(cached.snapshot, steps)) return cached;
  const snapshot = [];
  const grouped = new Map();
  steps.forEach((step, index) => {
    snapshot.push(
      step,
      step.id,
      step.parentId,
      step.sortOrder,
      step.step_type,
      step.autoGeneratedReference,
      step.enabled,
      step.branchType,
    );
    const key = step.parentId || null;
    if (!grouped.has(key)) grouped.set(key, []);
    grouped.get(key).push({ step, index });
  });
  const children = new Map();
  grouped.forEach((items, key) => {
    items.sort(
      (a, b) =>
        atlasStepOrderGroup(a.step) - atlasStepOrderGroup(b.step) ||
        (Number(a.step.sortOrder) || 0) - (Number(b.step.sortOrder) || 0) ||
        a.index - b.index,
    );
    children.set(
      key,
      items.map(({ step }) => step),
    );
  });
  const index = { snapshot, children, entries: new Map() };
  atlasStepHierarchyCache.set(steps, index);
  return index;
}

/**
 * Returns children of a parent sorted by required group, sortOrder, then original array order.
 * @param {any} parentId - Id of the parent step, or empty/null for top-level steps.
 */
function atlasOrderedSiblings(
  parentId,
  steps = (atlasDisplayDocument?.() || state.audit).steps || [],
) {
  return [
    ...(atlasStepHierarchyIndex(steps).children.get(parentId || null) || []),
  ];
}
/**
 * Returns all parent ids currently represented by steps.
 */
function atlasParentKeysForStepOrder(steps = state.audit.steps || []) {
  const keys = new Set([""]);
  steps.forEach((step) => keys.add(step.parentId || ""));
  return [...keys];
}
/**
 * Normalizes sortOrder values within each sibling group while preserving hierarchy.
 */
function atlasNormalizeStepOrderGroups() {
  let changed = false;
  // Sibling groups are disjoint, so one index serves every group even though
  // renumbering one group changes its sortOrder values.
  const { children } = atlasStepHierarchyIndex(
    (atlasDisplayDocument?.() || state.audit).steps || [],
  );
  atlasParentKeysForStepOrder().forEach((parentKey) => {
    (children.get(parentKey || null) || []).forEach((step, index) => {
      const next = index + 1;
      if (Number(step.sortOrder) !== next) {
        step.sortOrder = next;
        changed = true;
      }
    });
  });
  return changed;
}

// -----------------------------------------------------------------------------
// Hierarchy lookup and parent controls
// -----------------------------------------------------------------------------
/**
 * Looks up a step by id.
 * @param {any} id - Element id or record id to look up.
 */
function stepById(
  id,
  steps = (atlasDisplayDocument?.() || state.audit).steps || [],
) {
  if (id === null || id === undefined || id === "")
    return steps.find((step) => step.id === id) || null;
  // A remembered position is trusted only if that slot still holds the id.
  let positions = atlasStepIdPositions.get(steps);
  let position = positions?.get(id);
  if (position !== undefined && steps[position]?.id === id)
    return steps[position];
  positions = new Map();
  steps.forEach((step, index) => {
    if (!positions.has(step.id)) positions.set(step.id, index);
  });
  atlasStepIdPositions.set(steps, positions);
  position = positions.get(id);
  return position === undefined ? null : steps[position];
}

/**
 * Returns ordered child steps for a parent.
 * @param {any} parentId - Id of the parent step, or empty/null for top-level steps.
 */
function childrenOf(
  parentId,
  steps = (atlasDisplayDocument?.() || state.audit).steps || [],
) {
  return atlasOrderedSiblings(parentId, steps);
}

/**
 * Determines whether one step is nested beneath another.
 * @param {any} stepId - Id of the target logic step.
 * @param {any} potentialParentId - Input used by isDescendantOf.
 */
function isDescendantOf(stepId, potentialParentId) {
  let current = stepById(potentialParentId);
  while (current) {
    if (current.id === stepId) return true;
    current = current.parentId ? stepById(current.parentId) : null;
  }
  return false;
}

/**
 * Builds parent selection options for a step.
 * @param {any} step - Logic step object being read or modified.
 */
function parentOptionsForStep(step) {
  return [
    { id: "", label: "Top-level step" },
    ...state.audit.steps
      .filter(
        (candidate) =>
          candidate.id !== step.id && !isDescendantOf(step.id, candidate.id),
      )
      .map((candidate) => ({
        id: candidate.id,
        label: `${stepNumberFor(candidate.id) || "?"} ${candidate.title || stepTypeLabel(candidate.type)}`,
      })),
  ];
}

/**
 * Builds branch type option markup based on whether a step is nested.
 * @param {any} step - Logic step object being read or modified.
 */
function branchTypeOptions(step) {
  const values = step.parentId
    ? [
        ["then", "Then / Child"],
        ["else-if", "Else If"],
        ["else", "Else"],
      ]
    : [["root", "Top-level"]];
  return values
    .map(
      ([value, label]) =>
        `<option value="${value}" ${step.branchType === value ? "selected" : ""}>${label}</option>`,
    )
    .join("");
}

/**
 * Returns the display label for a step branch type.
 * @param {any} step - Logic step object being read or modified.
 */
function branchLabel(step) {
  if (!step.parentId) return "Root";
  if (step.branchType === "else-if") return "ELSE IF";
  if (step.branchType === "else") return "ELSE";
  return "THEN";
}

// -----------------------------------------------------------------------------
// Flattened hierarchy rendering data
// -----------------------------------------------------------------------------
/**
 * Flattens the step tree into display entries with hierarchy numbers.
 */
function hierarchicalStepEntries({
  includeDisabled = true,
  steps = (atlasDisplayDocument?.() || state.audit).steps || [],
} = {}) {
  if (steps === state.audit.steps) normalizeHierarchyFields(steps);
  const hierarchy = atlasStepHierarchyIndex(steps);
  const cacheKey = includeDisabled ? "all" : "enabled";
  const cached = hierarchy.entries.get(cacheKey);
  // Copies keep callers from mutating the cached entries.
  if (cached) return cached.map((entry) => ({ ...entry }));
  const entries = [];
  const counters = [];
  /**
   * Handles the visit portion of the ATLAS Align client-side workflow.
   * @param {any} parentId - Id of the parent step, or empty/null for top-level steps.
   * @param {any} level - Input used by visit.
   * @param {any} prefix - Action label prefix such as THEN or ELSE.
   */
  const visit = (parentId, level, prefix = []) => {
    const siblings = (hierarchy.children.get(parentId || null) || []).filter(
      (step) => includeDisabled || step.enabled !== false,
    );
    siblings.forEach((step, index) => {
      counters[level] = index + 1;
      counters.length = level + 1;
      const number = [...prefix, index + 1].join(".");
      entries.push({ step, level, number, branchLabel: branchLabel(step) });
      visit(step.id, level + 1, [...prefix, index + 1]);
    });
  };
  visit(null, 0, []);
  hierarchy.entries.set(cacheKey, entries);
  return entries.map((entry) => ({ ...entry }));
}

/**
 * Returns the hierarchy number for a step id.
 * @param {any} stepId - Id of the target logic step.
 */
function stepNumberFor(stepId) {
  const entry = hierarchicalStepEntries({ includeDisabled: true }).find(
    (item) => item.step.id === stepId,
  );
  return entry?.number || "";
}

/**
 * Moves a step to a new parent while preventing circular nesting.
 * @param {any} step - Logic step object being read or modified.
 * @param {any} parentId - Id of the parent step, or empty/null for top-level steps.
 */
function setStepParent(step, parentId) {
  const normalizedParent = parentId || null;
  if (normalizedParent === step.id || isDescendantOf(step.id, normalizedParent))
    return false;
  step.parentId = normalizedParent;
  step.branchType = normalizedParent
    ? step.branchType === "root"
      ? "then"
      : step.branchType || "then"
    : "root";
  step.sortOrder = childrenOf(normalizedParent).length + 1;
  return true;
}

/**
 * Indents a step one level, nesting it under its previous sibling.
 * Uses the sibling rather than the previous flattened entry so a step never
 * jumps into the deepest descendant of the step above it.
 * @param {any} step - Logic step object being read or modified.
 */
function makeChildOfPrevious(step) {
  const siblings = childrenOf(step.parentId);
  const index = siblings.findIndex((item) => item.id === step.id);
  if (index <= 0) return false;
  return setStepParent(step, siblings[index - 1].id);
}

/**
 * Moves a nested step up one hierarchy level.
 * @param {any} step - Logic step object being read or modified.
 */
function outdentStep(step) {
  const parent = stepById(step.parentId);
  if (!parent) return false;
  return setStepParent(step, parent.parentId || null);
}

// -----------------------------------------------------------------------------
// Step hierarchy mutations
// -----------------------------------------------------------------------------
/**
 * Creates a new child step underneath a parent step.
 * @param {any} parentStep - Input used by addChildStep.
 */
function addChildStep(parentStep) {
  capture();
  const child = {
    id: uid("step"),
    enabled: true,
    title: "New Child Logic Step",
    type: "if",
    parentId: parentStep.id,
    branchType: "then",
    sortOrder: childrenOf(parentStep.id).length + 1,
    source: parentStep.source || "",
    field: parentStep.field || "",
    action: "",
    notes: "",
    conditions: [{ id: uid("cond"), field: "", operator: "equals", value: "" }],
  };
  state.audit.steps.push(child);
  state.selectedStepId = child.id;
  atlasRequestStructuralStepRender?.();
  showSection("steps");
  scheduleAutosave();
}
